SELECT 'core-2026-09-v4','prepositions-of-time','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"prepositions-of-time","title":"Prepositions of time","level":"A1","order":17,"summary":"Practise at, on, in and no preposition with unambiguous time expressions.","learningGoals":["At","On and in","No preposition"],"guidance":"Read the short rules and examples, then complete a 20-question session. Use feedback to explain each choice. Revisit the skill you missed before trying again.","rules":[{"title":"At","explanation":"Use at with clock times and expressions such as noon, midnight and dawn.","examples":["The gates open at 8:15.","We leave at sunrise."]},{"title":"On and in","explanation":"Use on with days and dates, including a named day plus a part of that day. Use in with months and with the morning, afternoon or evening.","examples":["on Thursday afternoon","in November"]},{"title":"No preposition","explanation":"Usually omit a time preposition before next, last, this or every, and before today, tomorrow and yesterday. Here, — means leave the gap empty.","examples":["The rehearsal is next week.","I will call tomorrow."]}],"tips":["Read the full context before choosing.","Check the explanation, including after a correct answer.","A passing practice session is useful feedback, not a language certificate."],"source":"seed","provenance":{"version":"foundations-2026-09-v1","authorship":"Grammacho; generated offline with AI assistance","kind":"original-guidance-aligned","reviewStatus":"automated-checked; educator-review-pending","referenceIds":["bc-time","pcc-esol"],"assessment":"Practice only; levels are approximate teaching labels, not validated CEFR assessment."},"chapter":{"introduction":["Time prepositions group expressions by how English conventionally presents them: as a point, a day/date or a larger period. These are useful patterns rather than rules based only on duration. Some expressions take no preposition at all."],"rules":[{"title":"At","explanation":"Use at with clock times and expressions such as noon, midnight and dawn.","examples":["The gates open at 8:15.","We leave at sunrise.","We meet **at** noon **on** Friday."],"pattern":"**at** six · **at** night","paragraphs":["At commonly introduces clock times and certain fixed time expressions such as at night and at the moment. A festival period may take at in British English: at Christmas. When naming the particular day, use on Christmas Day."],"id":"prepositions-of-time-foundation-1","domain":"prepositions","referenceIds":["bc-time","pcc-esol"],"readingVersion":"foundations-2026-09-v1"},{"title":"On and in","explanation":"Use on with days and dates, including a named day plus a part of that day. Use in with months and with the morning, afternoon or evening.","examples":["on Thursday afternoon","in November","She was born **in** April **in** 2001."],"pattern":"**on** Monday · **on** 12 May · **on** Friday morning","paragraphs":["On introduces days and dates. Adding a day to a part of the day usually changes in to on: in the morning but on Tuesday morning. English names of days and months begin with capitals."],"id":"prepositions-of-time-foundation-2","domain":"prepositions","referenceIds":["bc-time","pcc-esol"],"readingVersion":"foundations-2026-09-v1"},{"title":"No preposition","explanation":"Usually omit a time preposition before next, last, this or every, and before today, tomorrow and yesterday. Here, — means leave the gap empty.","examples":["The rehearsal is next week.","I will call tomorrow.","I’ll see you **next Monday**, not on next Monday."],"pattern":"**in** June · **in** 2030 · **in** the morning","paragraphs":["In introduces months, years, seasons and many parts of the day. It can also mean after a period from now: in ten minutes. For gives a duration and since gives a starting point; they answer different time questions."],"id":"prepositions-of-time-foundation-3","domain":"prepositions","referenceIds":["bc-time","pcc-esol"],"readingVersion":"foundations-2026-09-v1"},{"title":"Contrasts and edge cases","explanation":"Next, last, this and every usually come without in/on/at: next week, last year, this morning, every Friday. British at the weekend and American on the weekend are both standard patterns. By marks a deadline; until marks continuation up to a point.","examples":["We meet **at** noon **on** Friday.","She was born **in** April **in** 2001.","I’ll see you **next Monday**, not on next Monday."],"id":"prepositions-of-time-foundation-4","domain":"prepositions","referenceIds":["bc-time","pcc-esol"],"readingVersion":"foundations-2026-09-v1"},{"domain":"prepositions","id":"time-preposition-contrasts","title":"During, for, since, by, until, within and throughout","explanation":"During locates an event within a period; for measures duration; since identifies a starting point. By sets a deadline, until marks continuation, and within gives an allowed interval. Throughout presents coverage over a whole period. Decide what relation is intended rather than translating a preposition word for word.","pattern":"finish **by Friday** / stay **until Friday**","examples":["She slept **during the film** for twenty minutes.","Please reply **within three days**."],"commonMistakes":["By Friday does not mean continuing until Friday. Since can combine with different tense frames and does not itself guarantee a present-perfect construction."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["**at** six · **at** night","**on** Monday · **on** 12 May · **on** Friday morning","**in** June · **in** 2030 · **in** the morning"],"readingVersion":"core-2026-09-v4"},"stage":"2 · Everyday descriptions","prerequisites":["determiners-quantifiers"],"readingReferenceIds":["bc-time","pcc-esol","cambridge-comprehensive-scope"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='prepositions-of-time'
